package com.hms.reminders;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="appointment_reminders") public class AppointmentReminder { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false) private UUID appointmentId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ReminderChannel channel; @Column(nullable=false) private OffsetDateTime remindAt; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ReminderStatus status; @Column(nullable=false) private OffsetDateTime createdAt; protected AppointmentReminder(){} public AppointmentReminder(UUID tenantId,UUID appointmentId,CreateReminderRequest r){id=UUID.randomUUID();this.tenantId=tenantId;this.appointmentId=appointmentId;channel=r.channel();remindAt=r.remindAt();status=ReminderStatus.SCHEDULED;createdAt=OffsetDateTime.now();} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public UUID getAppointmentId(){return appointmentId;} public ReminderChannel getChannel(){return channel;} public OffsetDateTime getRemindAt(){return remindAt;} public ReminderStatus getStatus(){return status;} }
